--[[
    VeevHUD - Portuguese (Brazil) (ptBR) Localization

    AI-GENERATED translation (by Claude) -- NOT yet reviewed by a native speaker.

    >> Contributions welcome! << Spotted an awkward or wrong string? Edit its
    L["..."] = "..." value below and open a pull request (or an issue) at
    https://github.com/veev-code/VeevHUD  -- native speakers especially appreciated.
    Any key omitted here falls back to English automatically (see enUS.lua).
]]

local L = LibStub("AceLocale-3.0"):NewLocale("VeevHUD", "ptBR")
if not L then return end

L["Outline"] = "Contorno"
L["Shadow"] = "Sombra"
L["Both"] = "Ambos"
L["None"] = "Nenhum"
L["Inherit (Global)"] = "Herdar (Global)"
L["Off"] = "Desligado"
L["Primary Row"] = "Linha Primária"
L["Primary + Secondary Rows"] = "Linhas Primária + Secundária"
L["Secondary + Utility Rows"] = "Linhas Secundária + Utilidade"
L["Utility Row"] = "Linha de Utilidade"
L["All Rows"] = "Todas as Linhas"
L["Prediction"] = "Previsão"
L["Fill"] = "Preenchimento"
L["Bar"] = "Barra"
L["Spark"] = "Brilho"
L["Current"] = "Atual"
